//! 🧪️ Actual network replacement preserves authored parallel arrays, source custody, sparse systems publication and every cancelled inverse prefix.
use crate::{snapshot::original::EnergyModelSnapshot,diff::original::EnergyModelDiff};
use protocol::{RetainedMutationLeaf,RetainedMutationLeafPreparation,RetainedMutationAdvance,RetainedMutationDecision,RetainedMutationCloseContext};
use semio_framework_value::ToValue;
#[path="../../../../📸️snapshot/🧳️state/🧪️tests/🧰️helpers/🦀️.rs"]mod helpers;
use helpers::{source,receive_retained,grant,observe,drain,denied_axes,project_record,central_fragment,assert_portable_value};
#[derive(Debug,semio_framework_value::ToValue,semio_framework_value::FromValue,semio_framework_value::RetireOwned)]
#[value(tag="mutation",rename_all="camelCase")]
enum Operation{ReplaceAirflowNetwork(crate::ReplaceAirflowNetwork)}
impl From<crate::ReplaceAirflowNetwork> for Operation{fn from(v:crate::ReplaceAirflowNetwork)->Self{Self::ReplaceAirflowNetwork(v)}}
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("actual original network law invokes its authored native leaf")}}
type Preparation=<crate::ReplaceAirflowNetwork as RetainedMutationLeaf<EnergyModelSnapshot,Operation>>::Preparation;
fn run(case:&serde_json::Value,law:&serde_json::Value){let mut doc:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut doc=doc["document"].take();doc["model"]=helpers::corpus()["model"].clone();doc["model"]["airflow_network"]=case["before"].clone();let original=source(receive_retained::<EnergyModelSnapshot>(&doc));let input=source(receive_retained::<crate::ReplaceAirflowNetwork>(&case["payload"]));let foreign=source(receive_retained::<crate::ReplaceAirflowNetwork>(&case["payload"]));let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<Operation>::default();let context=RetainedMutationCloseContext{mutations:&factory};
 let cuts=std::iter::once((None,None)).chain(law["cancelAt"].as_array().unwrap().iter().flat_map(|v|{let cut=v.as_u64().unwrap()as usize;[(Some(cut),None),(None,Some(cut))]}));
 for(decision_cut,inverse_cut)in cuts{let mut owner=Preparation::new();let mut ready=false;for turn in 0..decision_cut.unwrap_or(1000000){let d=owner.decision_demand(input.borrow(),original.borrow(),4096).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(input.borrow(),original.borrow(),4096).unwrap(),d);}let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if turn==2{assert!(owner.decision_demand(foreign.borrow(),original.borrow(),4096).is_err());}if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break;}}
 if decision_cut.is_none(){assert!(ready,"original network decision finishes");}let mut diff=None;let mut inverse=None;if ready{match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert_eq!(case["outcome"],"invalid");assert_eq!(messages.len(),1);assert_eq!(messages[0].code.0.as_str(),"mutation.invariant");assert!(messages[0].target.is_empty());drain(messages)},RetainedMutationDecision::Admitted(value,messages)=>{assert_ne!(case["outcome"],"invalid");let changed=case["outcome"]=="changed";if changed{assert!(messages.is_empty())}else{assert_eq!(messages.len(),1);assert_eq!(messages[0].code.0.as_str(),"mutation.no-op");}drain(messages);let value=source(value);if decision_cut.is_none()&&inverse_cut.is_none(){let mut post=project_record(original.borrow());assert!(central_fragment(&value,original.borrow(),&mut post));assert_portable_value(post.model.systems.get().airflow_network.to_value(),&case["after"]);macro_rules! sibling{($($branch:ident),*)=>{$(assert_eq!(post.model.$branch.identity(),original.borrow().get().model.$branch.identity());)*};}sibling!(identity,geometry,materials,loads,controls,generation,outputs);drain(post);}
 let mut complete=false;for _ in 0..inverse_cut.unwrap_or(1000000){let d=owner.inverse_demand(input.borrow(),original.borrow(),value.borrow(),4096).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){complete=true;break;}}if inverse_cut.is_none(){assert!(complete);}if complete{let operations=owner.take_inverse();assert_eq!(operations.len(),usize::from(changed));if changed{assert_portable_value(operations[0].to_value(),&case["inverse"]);}inverse=Some(operations);}diff=Some(value);}}}
 owner.begin_close();for _ in 0..1000000{if owner.terminal_is_empty(){break}let d=owner.close_demand(context,4096).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,4096).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(value)=diff{drain(value)}if let Some(value)=inverse{drain(value)}
 }drain(foreign);drain(input);drain(original);
}
#[test]fn actual_original_network_optional_singleton_keeps_complete_inverse_source_denials_and_cancellation(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){run(case,&law);}}
#[test]fn wide_original_network_pairs_and_inverse_split_each_item_under_the_same_body(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let n=law["widePairCount"].as_u64().unwrap()as usize;let before=serde_json::json!({"zone_node_ids":(0..n).map(|i|[i,i+17]).collect::<Vec<_>>(),"outdoor_node_id":77,"link_ids":(0..n).map(|i|i+31).collect::<Vec<_>>()});let payload=serde_json::json!({"present":true,"zoneIds":(0..n).rev().collect::<Vec<_>>(),"nodeIds":(0..n).rev().map(|i|i+17).collect::<Vec<_>>(),"outdoorNodeId":77,"linkIds":(0..n).rev().map(|i|i+31).collect::<Vec<_>>()});let after=serde_json::json!({"zone_node_ids":(0..n).rev().map(|i|[i,i+17]).collect::<Vec<_>>(),"outdoor_node_id":77,"link_ids":payload["linkIds"]});let inverse=serde_json::json!({"mutation":"replaceAirflowNetwork","present":true,"zoneIds":(0..n).collect::<Vec<_>>(),"nodeIds":(0..n).map(|i|i+17).collect::<Vec<_>>(),"outdoorNodeId":77,"linkIds":before["link_ids"]});run(&serde_json::json!({"before":before,"payload":payload,"after":after,"inverse":inverse,"outcome":"changed"}),&law);}
